arguments.command:
git checkout feat/BKG-90 2>&1 | tail -1 && cat > spec/cancel.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" && grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "header or other booking lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
rm -f "$t"
# F-3: another room with the same date and start must stay
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel F-3 failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "other room booking removed"; fail=1; }
! grep -q '^aoi' "$t" || { echo "aoi booking still there (F-3)"; fail=1; }
rm -f "$t"
# F-1: not found goes to stderr with exit 1 and nothing on stdout
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ "$rc" = 1 ] && [ -z "$out" ] || { echo "not found: rc=$rc stdout=[$out] (F-1)"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found stderr: [$err] (F-1)"; fail=1; }
rm -f "$t"
# F-2: wrong argument count is exit 2 with usage on stderr and nothing on stdout
out=$(bash src/cancel.sh aoi 2>/dev/null); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] || { echo "usage: rc=$rc stdout=[$out] (F-2)"; fail=1; }
err=$(bash src/cancel.sh aoi 2>&1 >/dev/null)
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage stderr: [$err] (F-2)"; fail=1; }
exit $fail
EOF
echo "== repro on branch (before fix)"; bash spec/cancel.spec.sh; echo "rc=$?"

